import { createClient } from 'supabase';
const N=(x:any)=>x===null||x===undefined||x===''?null:Number(x);const clamp=(x:number,a=0,b=1)=>Math.max(a,Math.min(b,x));
const pos=(p:any)=>{const s=String(p||'').toLowerCase();if(s==='gkp'||s.includes('goal'))return'GKP';if(s==='def'||s.includes('def'))return'DEF';if(s==='mid'||s.includes('mid'))return'MID';if(s==='fwd'||s.includes('forw'))return'FWD';return'UNK'};
function tail(l:number,k:number){if(l<=0)return 0;let p=Math.exp(-l),s=p;for(let i=1;i<k;i++){p*=l/i;s+=p}return clamp(1-s)}
Deno.serve(async()=>{const ks=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');const sb=createClient(Deno.env.get('SUPABASE_URL')!,ks.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false}});try{
const [{data:mv},{data:pl},{data:h},{data:e},{data:pre},{data:fm}]=await Promise.all([sb.from('model_versions').select('id,version').eq('is_active',true).single(),sb.from('players').select('id,player_code,position,status,team_id,chance_of_playing_next_round'),sb.from('historical_player_seasons').select('*').eq('season','2025-2026'),sb.from('external_player_seasons').select('*').eq('season','2025-2026'),sb.from('player_matches').select('player_id,minutes,started,xg,xa,cbit,cbirt').eq('source','fpl_core_insights'),sb.from('matches').select('home_team_id,away_team_id,raw').eq('source','fpl_core_insights').eq('competition','friendly')]);if(!mv)throw new Error('active model missing');
const hm=new Map((h||[]).map((x:any)=>[Number(x.player_code),x])),em=new Map((e||[]).map((x:any)=>[Number(x.player_code),x]));const games=new Map<number,number>();for(const m of fm||[]){if(String(m.raw?.player_stats_processed??'').toLowerCase()!=='true')continue;for(const t of [m.home_team_id,m.away_team_id])if(t)games.set(Number(t),(games.get(Number(t))||0)+1)}
const pa=new Map<number,any>();for(const r of pre||[]){const mins=N(r.minutes)||0;if(mins<=0)continue;let a=pa.get(Number(r.player_id));if(!a){a={apps:0,starts:0,mins:0,xg:0,xgm:0,xa:0,xam:0,cbit:0,cbirt:0,dcmins:0};pa.set(Number(r.player_id),a)}a.apps++;a.starts+=r.started?1:0;a.mins+=mins;if(N(r.xg)!==null){a.xg+=Number(r.xg);a.xgm+=mins}if(N(r.xa)!==null){a.xa+=Number(r.xa);a.xam+=mins}a.cbit+=N(r.cbit)||0;a.cbirt+=N(r.cbirt)||0;a.dcmins+=mins}
const pagg=new Map<string,any>();for(const x of h||[]){if((N(x.minutes)||0)<450)continue;const q=pos(x.position);let a=pagg.get(q);if(!a){a={mins:0,xg:0,xa:0,cbit:0,cbirt:0};pagg.set(q,a)}a.mins+=N(x.minutes)||0;a.xg+=N(x.xg)||0;a.xa+=N(x.xa)||0;a.cbit+=N(x.cbit)||0;a.cbirt+=N(x.cbirt)||0}const pr=(a:any,k:string)=>a?.mins?90*a[k]/a.mins:0;
const at=new Date().toISOString(),rows:any[]=[];for(const p of pl||[]){const H=hm.get(Number(p.player_code)),E=em.get(Number(p.player_code)),A=pa.get(Number(p.id)),P=pos(p.position),B=pagg.get(P);const hmch=N(H?.matches)||0,hst=N(H?.starts)||0,hmin=N(H?.minutes)||0,emch=N(E?.matches)||0,est=N(E?.starts)||0,emin=N(E?.minutes)||0,apps=A?.apps||0;
const generic=.35,hRate=H?(hst+generic*4)/(hmch+4):null,eRate=E&&emch?(est/emch):null,preRate=apps?A.starts/apps:null;const hw=H?Math.min(20,Math.max(8,hmch*.45)):0,ew=E&&!H?Math.min(8,emch*(N(E.evidence_weight)||.5)*.4):0,pw=preRate===null?0:(H?Math.min(4,apps*.75):Math.min(8,apps*1.5)),gw=H||E?0:3;let sp=(hw*(hRate??0)+ew*(eRate??0)+pw*(preRate??0)+gw*generic)/(hw+ew+pw+gw||1);
const startMins=(matches:number,starts:number,mins:number,rate:number|null)=>{if(P==='GKP')return 90;if(!matches||!rate||rate<=0)return 70;const mpa=mins/matches,sub=Math.max(0,1-rate);return clamp((mpa-sub*18)/rate,50,90)};const hsm=H?startMins(hmch,hst,hmin,hRate):70,esm=E?startMins(emch,est,emin,eRate):70,psm=preRate?clamp(((A.mins/apps)-Math.max(0,1-preRate)*18)/preRate,45,90):70;let sm=(hw*hsm+ew*esm+pw*psm+(gw||0)*70)/(hw+ew+pw+gw||1);
let ap=(H||E||apps)?0.98:0.20;const fallback=p.status==='a'?1:p.status==='d'?.75:(p.status==='i'||p.status==='u')?.1:p.status==='n'?.3:.8,avail=N(p.chance_of_playing_next_round)??fallback;sp*=avail;ap*=avail;
if(sp>=.75){const floor=P==='GKP'?90:P==='DEF'?(sp>=.9?84:80):P==='MID'?(sp>=.9?80:74):(sp>=.9?76:70);sm=Math.max(sm,floor)}
const xmin=sp*sm+Math.max(0,ap-sp)*18;
const blend=(metric:string)=>{const br=pr(B,metric),hr=H&&hmin?90*(N(H[metric])||0)/hmin:null;let er:number|null=null;if(E&&emin){if(metric==='xg')er=90*(N(E.npxg)??N(E.xg)??0)/emin;else if(metric==='xa')er=90*(N(E.xa)||0)/emin;else if(metric==='cbit')er=90*((N(E.clearances)||0)+(N(E.blocks)||0)+(N(E.interceptions)||0)+(N(E.tackles)||0))/emin;else if(metric==='cbirt')er=90*((N(E.clearances)||0)+(N(E.blocks)||0)+(N(E.interceptions)||0)+(N(E.tackles)||0)+(N(E.recoveries)||0))/emin}const pm=A&&A.dcmins?90*(A[metric]||0)/A.dcmins:null,obsMin=metric==='xg'?A?.xgm:metric==='xa'?A?.xam:A?.dcmins;const prior=450,hW=H?Math.min(1800,hmin):0,eW=E&&!H?Math.min(1200,emin*(N(E.evidence_weight)||.5)):0,pW=pm===null?0:Math.min(500,obsMin||0);return(br*prior+(hr??0)*hW+(er??0)*eW+(pm??0)*pW)/(prior+hW+eW+pW||1)};
const xg=blend('xg'),xa=blend('xa'),cb=blend('cbit'),cbr=blend('cbirt'),lam=(P==='DEF'?cb:cbr)*xmin/90,dc=P==='DEF'?tail(lam,10):(P==='MID'||P==='FWD')?tail(lam,12):0,conf=clamp(.2+.4*Math.min(1,hmin/1800)+.18*Math.min(1,emin/1800)+.22*Math.min(1,apps/4),.15,.95);
rows.push({player_id:p.id,as_of:at,model_version_id:mv.id,sample_matches:hmch+emch+apps,expected_minutes:+xmin.toFixed(2),start_probability:+sp.toFixed(4),appearance_probability:+ap.toFixed(4),starter_minutes_estimate:+sm.toFixed(2),xg90:+xg.toFixed(4),xa90:+xa.toFixed(4),xgi90:+(xg+xa).toFixed(4),cbit90:+cb.toFixed(3),cbirt90:+cbr.toFixed(3),dc_probability:+dc.toFixed(4),state:{model:'bayesian_v0.1.2',historical_pl:{matches:hmch,starts:hst,minutes:hmin,weight:hw},external:E?{competition:E.competition,source:E.source,matches:emch,starts:est,minutes:emin,evidence_weight:E.evidence_weight,model_weight:ew}:null,preseason:{apps,starts:A?.starts||0,minutes:A?.mins||0,weight:pw},availability:avail,confidence:conf,xmins_floor_applied:sp>=.75}})}for(let i=0;i<rows.length;i+=200){const {error}=await sb.from('player_state').insert(rows.slice(i,i+200));if(error)throw error}return Response.json({ok:true,version:mv.version,players:rows.length,as_of:at})}catch(e){return Response.json({ok:false,error:e instanceof Error?e.message:String(e)},{status:500})}});
